// Some portions generated by Claude Code

const test = require('node:test');
const assert = require('node:assert/strict');
const { MemoryWorker, loadApi } = require('./query-load-more-harness.js');

const recoveryPrefix = 'rdf4j.workbench.query-results.pending-disposal.v1:';

/** A worker whose IndexedDB cannot be opened: it answers every request like queryStreamWorker does then. */
class UnavailableStorageWorker extends MemoryWorker {
    postMessage(message) {
        this.messages.push(message);
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: false, unavailable: true,
                error: 'IndexedDB is unavailable for Workbench query results.' };
            for (const callback of this.listeners.get('message') || []) callback({ data: response });
        });
    }
}

async function exerciseStore(store) {
    assert.equal(await store.count(), 0);
    assert.equal(await store.append([[{ kind: 'literal', value: 'a' }], [{ kind: 'literal', value: 'b' }]]), 2);
    assert.equal(await store.append([[{ kind: 'literal', value: 'c' }]]), 3);
    assert.deepEqual([...(await store.read(1, 5)).map(row => row[0].value)], ['b', 'c']);
    assert.equal((await store.read(5, 2)).length, 0);
    await assert.rejects(store.read(-1, 2), /non-negative/i);
    await assert.rejects(store.append('rows'), /batch/i);
    assert.equal(await store.truncate(1), 1);
    await assert.rejects(store.truncate(2), /exceed/i);
    await assert.rejects(store.truncate(-1), /non-negative/i);
    assert.equal(await store.count(), 1);
    await store.dispose();
    await store.dispose();
    await assert.rejects(store.append([[null]]), /disposed/i);
}

// Review finding B21: without Web Workers or IndexedDB, the Workbench keeps working on an in-memory row store.
test('createRowStore falls back to an in-memory store when Web Workers are unavailable', async () => {
    const { api } = loadApi();
    const store = await api.createRowStore();
    await exerciseStore(store);
});

test('createRowStore falls back to an in-memory store when the worker cannot open IndexedDB', async () => {
    const { api } = loadApi();
    const worker = new UnavailableStorageWorker();
    const store = await api.createRowStore({ workerFactory: () => worker });
    assert.equal(worker.terminated, true, 'the unusable worker is closed');
    await exerciseStore(store);
    assert.equal(worker.messages.length, 1, 'the in-memory store does not talk to the worker');
});

test('createRowStore falls back to an in-memory store when the worker factory throws or the worker dies', async () => {
    const { api } = loadApi();
    const thrown = await api.createRowStore({ workerFactory() { throw new Error('Workers are blocked.'); } });
    await exerciseStore(thrown);

    const dying = new MemoryWorker();
    dying.postMessage = function() {
        queueMicrotask(() => {
            for (const callback of this.listeners.get('error') || []) callback({ message: 'Script blocked.' });
        });
    };
    const died = await api.createRowStore({ workerFactory: () => dying });
    assert.equal(dying.terminated, true);
    await exerciseStore(died);
});

// Round 2 (R13): the in-memory fallback is bounded, so a million-row batch cannot exhaust the tab, and it says so.
test('the in-memory fallback store keeps at most its row limit and says why it refuses more', async () => {
    const { api } = loadApi();
    assert.equal(api.MEMORY_ROW_STORE_LIMIT, 100000);
    const store = await api.createRowStore({ memoryRowLimit: 3 });
    assert.equal(store.inMemory, true, 'the store says it lives in memory');
    assert.equal(await store.append([[null], [null]]), 2);
    await assert.rejects(store.append([[null], [null]]),
        /Browser storage is unavailable here, so the Workbench keeps at most 3 rows in memory\. Add a LIMIT/);
    assert.equal(await store.count(), 2, 'a batch that does not fit is not kept in part');
    assert.equal(await store.append([[null]]), 3, 'rows that fit are still kept');
    await store.dispose();
});

test('in-memory row stores are not marked for IndexedDB recovery', async () => {
    const { api, window } = loadApi();
    await api.createRowStore();
    api.markCurrentRowStoresForRecovery({ persisted: false });
    assert.equal(window.localStorage.length, 0);
});

test('recoverPendingRowStores resolves and keeps its markers when Workers are unavailable', async () => {
    const { api, window } = loadApi();
    window.localStorage.setItem(recoveryPrefix + 'old-store', 'pending');
    await api.recoverPendingRowStores();
    assert.equal(window.localStorage.getItem(recoveryPrefix + 'old-store'), 'pending',
        'a later boot with storage can still reclaim it');
});

function loadWorker(scopeOverrides = {}, globals = {}) {
    const fs = require('node:fs');
    const path = require('node:path');
    const vm = require('node:vm');
    const listeners = [];
    const responses = [];
    const scope = Object.assign({
        addEventListener(type, listener) { if (type === 'message') listeners.push(listener); },
        postMessage(response) { responses.push(response); }
    }, scopeOverrides);
    const workerPath = path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts/queryStreamWorker.js');
    vm.runInContext(fs.readFileSync(workerPath, 'utf8'), vm.createContext(Object.assign({ self: scope }, globals)),
        { filename: workerPath });
    return {
        responses,
        async send(message) {
            listeners.forEach(listener => listener({ data: message }));
            for (let count = 0; count < 200
                    && !responses.some(response => response.requestId === message.requestId); count++) {
                await new Promise(resolve => setImmediate(resolve));
            }
            return responses.filter(response => response.requestId === message.requestId).pop();
        }
    };
}

/** A small in-memory IndexedDB: enough object-store, cursor and transaction behaviour for the row-store worker. */
function fakeIndexedDB() {
    const objectStores = new Map();
    const compare = (a, b) => {
        if (Array.isArray(a) && Array.isArray(b)) {
            for (let index = 0; index < Math.min(a.length, b.length); index++) {
                const result = compare(a[index], b[index]);
                if (result) return result;
            }
            return a.length - b.length;
        }
        if (typeof a !== typeof b) return typeof a === 'number' ? -1 : 1;
        return a < b ? -1 : a > b ? 1 : 0;
    };
    const isRange = (key) => key && typeof key === 'object' && !Array.isArray(key) && 'lower' in key;
    const inRange = (key, range) => !range || (isRange(range)
        ? compare(key, range.lower) >= 0 && compare(key, range.upper) <= 0 : compare(key, range) === 0);
    const keyOf = (keyPath, value) => Array.isArray(keyPath) ? keyPath.map((name) => value[name]) : value[keyPath];
    const clone = (value) => value === undefined ? undefined : JSON.parse(JSON.stringify(value));
    const database = {
        objectStoreNames: { contains: (name) => objectStores.has(name) },
        createObjectStore(name, options) { objectStores.set(name, { keyPath: options.keyPath, records: [] }); },
        close() {},
        transaction() {
            const transaction = { pending: 0, done: false, aborted: false, error: null,
                oncomplete: null, onerror: null, onabort: null };
            const settle = () => setImmediate(() => {
                if (transaction.pending === 0 && !transaction.done && !transaction.aborted) {
                    transaction.done = true;
                    if (transaction.oncomplete) transaction.oncomplete();
                }
            });
            const request = (produce) => {
                const result = { result: undefined, error: null, onsuccess: null };
                transaction.pending++;
                setImmediate(() => {
                    result.result = produce();
                    if (!transaction.aborted && result.onsuccess) result.onsuccess({ target: result });
                    transaction.pending--;
                    settle();
                });
                return result;
            };
            transaction.abort = () => {
                transaction.aborted = true;
                setImmediate(() => transaction.onabort && transaction.onabort());
            };
            transaction.objectStore = (name) => {
                const store = objectStores.get(name);
                const sorted = () => store.records.slice().sort((a, b) => compare(a.key, b.key));
                const write = (value) => {
                    const key = keyOf(store.keyPath, value);
                    store.records = store.records.filter((record) => compare(record.key, key) !== 0);
                    store.records.push({ key, value: clone(value) });
                };
                return {
                    add: (value) => request(() => write(value)),
                    put: (value) => request(() => write(value)),
                    get: (key) => request(() => clone((store.records.find((record) => compare(record.key, key) === 0)
                        || {}).value)),
                    delete: (key) => request(() => {
                        store.records = store.records.filter((record) => !inRange(record.key, key));
                    }),
                    openCursor(range, direction) {
                        const result = { result: null, error: null, onsuccess: null };
                        let position = 0;
                        const step = () => {
                            transaction.pending++;
                            setImmediate(() => {
                                const matching = sorted().filter((record) => inRange(record.key, range));
                                if (direction === 'prev') matching.reverse();
                                const record = matching[position];
                                result.result = record ? {
                                    key: record.key, value: clone(record.value),
                                    continue() { position++; step(); },
                                    update(value) { return request(() => write(value)); }
                                } : null;
                                if (!transaction.aborted && result.onsuccess) result.onsuccess({ target: result });
                                transaction.pending--;
                                settle();
                            });
                        };
                        step();
                        return result;
                    }
                };
            };
            settle();
            return transaction;
        }
    };
    return {
        objectStores,
        indexedDB: {
            open() {
                const request = { result: database, error: null };
                setImmediate(() => {
                    if (!objectStores.size && request.onupgradeneeded) request.onupgradeneeded();
                    request.onsuccess();
                });
                return request;
            }
        },
        IDBKeyRange: { bound: (lower, upper) => ({ lower, upper }) }
    };
}

test('the row-store worker reports unavailable IndexedDB as such, with a readable message', async () => {
    const worker = loadWorker();
    const response = await worker.send({ op: 'create', requestId: 1 });
    assert.equal(response.ok, false);
    assert.equal(response.unavailable, true);
    assert.equal(response.error, 'IndexedDB is unavailable for Workbench query results.');

    const blocked = loadWorker({ indexedDB: { open() { throw Object.assign(new Error('The operation is insecure.'),
        { name: 'SecurityError' }); } } });
    const refused = await blocked.send({ op: 'create', requestId: 2 });
    assert.equal(refused.ok, false);
    assert.equal(refused.unavailable, true, 'a browser that refuses to open IndexedDB makes storage unavailable');
    // Review finding B25: the message is shown, with the error name only where it says something.
    assert.equal(refused.error, 'SecurityError: The operation is insecure.');
});

